# Palettes prêtes à l'emploi pour remplir les emplacements libres (contrastes valides).
PRESETS = [
    ("Prune", "#8a4d76", "#fa7c91", "#3e8ed0", "#f5f5f5", "#2c3e50", "#95a5a6"),
    ("Forêt", "#2f6b4f", "#e0a458", "#4f8a8b", "#f4f6f1", "#1f2d24", "#7d8a80"),
    ("Océan", "#1f5f8b", "#f4a259", "#5b8e7d", "#f3f7fa", "#1b2a38", "#8395a7"),
    ("Terracotta", "#a4462f", "#e9b44c", "#50808e", "#faf6f1", "#3b2a24", "#9c8b80"),
    ("Ardoise", "#3d4a5c", "#e07a5f", "#81b29a", "#f4f5f7", "#222831", "#8d96a3"),
]
PRESET_FIELDS = [
    "primary_color",
    "secondary_color",
    "tertiary_color",
    "background_color",
    "text_color",
    "text_muted_color",
]
COLOR_FIELDS = PRESET_FIELDS + [
    "navbar_follows_primary",
    "navbar_bg",
    "navbar_text",
    "navbar_hover_bg",
]
SLOTS = 5


def save_existing_palettes(apps, schema_editor):
    """Les couleurs actuelles de chaque site deviennent une palette ; le reste est complété par des presets."""
    Palette = apps.get_model("core", "Palette")
    ThemeSettings = apps.get_model("core", "ThemeSettings")

    slot = 0
    by_colors = {}
    for theme in ThemeSettings.objects.select_related("site").order_by(
        "-site__is_default_site", "pk"
    ):
        colors = {field: getattr(theme, field) for field in COLOR_FIELDS}
        key = tuple(colors.values())
        if key not in by_colors:
            if slot == SLOTS:
                continue  # plus d'emplacement libre : ce site prendra la palette n° 1
            slot += 1
            name = f"Palette {theme.site.site_name or theme.site.hostname}"[:50]
            by_colors[key] = Palette.objects.create(slot=slot, name=name, **colors)
        theme.palette = by_colors[key]
        theme.save(update_fields=["palette"])

    for name, *values in PRESETS[: SLOTS - slot]:
        slot += 1
        Palette.objects.create(slot=slot, name=name, **dict(zip(PRESET_FIELDS, values)))


def grant_palettes_to_moderators(apps, schema_editor):
    from django.contrib.auth.management import create_permissions

    app_config = apps.get_app_config("core")
    app_config.models_module = True
    create_permissions(app_config, apps=apps, verbosity=0)
    app_config.models_module = None

    Group = apps.get_model("auth", "Group")
    Permission = apps.get_model("auth", "Permission")
    group = Group.objects.filter(name="Modérateurs").first()
    if group:
        group.permissions.add(
            *Permission.objects.filter(
                content_type__app_label="core",
                codename__in=["change_palette", "view_palette"],
            )
        )


def restore_theme_colors(apps, schema_editor):
    ThemeSettings = apps.get_model("core", "ThemeSettings")
    for theme in ThemeSettings.objects.select_related("palette").exclude(palette=None):
        for field in COLOR_FIELDS:
            setattr(theme, field, getattr(theme.palette, field))
        theme.save()


